417: /**
418:  * @brief 旋转自检：用"像素里编码自己坐标"的图案转一次，抽查若干目的点。
419:  *
420:  * @details 判据是**坐标**而不是颜色：源 32x32 每像素写 (x<<11)|(y<<5)，
421:  *          转 30° 后对抽查点做逆变换求源点，读回来的坐标必须落在 ±2 px 内
422:  *          （EPIC 最近邻 + 亚像素）。失败时把第一处"期望 vs 实际"打出来 ——
423:  *          角度正负、pivot 语义错了都能从那一行反推。
424:  */
425: bool myvendor_epic_rotate_selftest(void)
426: {
427:   enum
428:   {
429:     SRC_W = 32, SRC_H = 32, DST_W = 48, DST_H = 48, PIV = 16, ANGLE = 300,
430:     PROBES = 10
431:   };
432:   static uint16_t src[SRC_W * SRC_H];
433:   static uint16_t dst[DST_W * DST_H];
434:   static const int16_t probe[PROBES][2] =
435:   {
436:     { 24, 24 }, { 24, 12 }, { 24, 36 }, { 12, 24 }, { 36, 24 },
437:     { 16, 16 }, { 32, 32 }, { 32, 16 }, { 16, 32 }, { 24, 6 }
438:   };
439:   const int32_t cx = DST_W / 2;
440:   const int32_t cy = DST_H / 2;
441:   const double th = (double)ANGLE * 0.1 * M_PI / 180.0;
442:   int32_t x;
443:   int32_t y;
444:   int32_t i;
445:   int32_t fails = 0;
446: 
447:   for (y = 0; y < SRC_H; y++)
448:     {
449:       for (x = 0; x < SRC_W; x++)
450:         {
451:           src[y * SRC_W + x] = (uint16_t)(((uint16_t)x << 11)
452:             | ((uint16_t)y << 5));
453:         }
454:     }
455:   memset(dst, 0, sizeof(dst));
456: 
457:   if (!myvendor_epic_rotate(src, SRC_W * sizeof(uint16_t), SRC_W, SRC_H,
458:           dst, DST_W * sizeof(uint16_t), DST_W, DST_H, ANGLE, PIV, PIV,
459:           cx, cy))
460:     {
461:       syslog(LOG_WARNING, "[vrot] selftest SKIP: epic rotate unavailable");
462:       return false;
463:     }
464: 
465:   for (i = 0; i < PROBES; i++)
466:     {
467:       /* 目的 (u,v) → 源：s = piv + R(-θ)·((u,v) - c)，θ 顺时针（y 向下）。 */
468:       const double du = (double)(probe[i][0] - cx);
469:       const double dv = (double)(probe[i][1] - cy);
470:       const double sx = (double)PIV + (cos(th) * du + sin(th) * dv);
471:       const double sy = (double)PIV + (-sin(th) * du + cos(th) * dv);
472:       const int32_t rx = (int32_t)lround(sx);
473:       const int32_t ry = (int32_t)lround(sy);
474:       uint16_t got;
475:       int32_t gx;
476:       int32_t gy;
477: 
478:       if (rx < 0 || ry < 0 || rx >= SRC_W || ry >= SRC_H)
479:         {
480:           continue;                /* 该点落在源的空白区 */
481:         }
482: 
483:       got = dst[probe[i][1] * DST_W + probe[i][0]];
484:       gx = (int32_t)((got >> 11) & 0x1F);
485:       gy = (int32_t)((got >> 5) & 0x3F);
486: 
487:       if (abs((int)(gx - rx)) > 2 || abs((int)(gy - ry)) > 2)
488:         {
489:           if (fails == 0)
490:             {
491:               syslog(LOG_WARNING,
492:                 "[vrot] selftest fail dst(%d,%d): expect src(%d,%d) got (%d,%d) raw=0x%04x",
493:                 (int)probe[i][0], (int)probe[i][1], (int)rx, (int)ry,
494:                 (int)gx, (int)gy, (unsigned)got);
495:             }
496:           fails++;
497:         }
498:     }
499: 
500:   syslog((fails == 0) ? LOG_NOTICE : LOG_WARNING,
501:     "[vrot] selftest %s: %d probes, %d fail",
502:     (fails == 0) ? "PASS" : "FAIL", (int)PROBES, (int)fails);
503: 
504:   return fails == 0;
505: }
